solutionCode:
#[derive(Debug)]
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

pub fn mostra(p: Ponto) -> String {
    format!("{:?}", p)
}

testsCode:
use desafio::mostra;
use desafio::ponto_de;

#[test]
fn testa_a_estampa_do_ponto_dois_por_tres() {
    assert_eq!(mostra(ponto_de(2, 3)), "Ponto { x: 2, y: 3 }");
}

#[test]
fn testa_a_estampa_do_ponto_origem() {
    assert_eq!(mostra(ponto_de(0, 0)), "Ponto { x: 0, y: 0 }");
}
